def factorial(number):
    if number < 0:
        raise ValueError("階乘只定義於非負整數")
    if number <= 1:
        return 1
    return number * factorial(number - 1)

print(factorial(5))  # 120

def binary_strings(length, prefix=""):
    if length == 0:
        return [prefix]
    return (
        binary_strings(length - 1, prefix + "0")
        + binary_strings(length - 1, prefix + "1")
    )

print(binary_strings(2))  # ['00', '01', '10', '11']

def fibonacci(number):
    if number <= 1:
        return number
    return fibonacci(number - 1) + fibonacci(number - 2)

print(fibonacci(6))  # 8

def divide_max(numbers, left, right):
    if left == right:
        return numbers[left]
    middle = (left + right) // 2
    left_max = divide_max(numbers, left, middle)
    right_max = divide_max(numbers, middle + 1, right)
    return max(left_max, right_max)

def maximum(numbers):
    if not numbers:
        raise ValueError("陣列不可為空")
    return divide_max(numbers, 0, len(numbers) - 1)

print(maximum([7, 2, 9, 4]))  # 9

def merge_sort(numbers):
    if len(numbers) <= 1:
        return numbers[:]
    middle = len(numbers) // 2
    left = merge_sort(numbers[:middle])
    right = merge_sort(numbers[middle:])

    merged = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            merged.append(left[i]); i += 1
        else:
            merged.append(right[j]); j += 1
    return merged + left[i:] + right[j:]

def quick_sort(numbers):
    if len(numbers) <= 1:
        return numbers[:]
    pivot = numbers[len(numbers) // 2]
    lower = [value for value in numbers if value < pivot]
    equal = [value for value in numbers if value == pivot]
    higher = [value for value in numbers if value > pivot]
    return quick_sort(lower) + equal + quick_sort(higher)

print(quick_sort([5, 2, 8, 2, 1]))  # [1, 2, 2, 5, 8]

def all_binary_choices(length):
    results = []
    path = []

    def backtrack():
        if len(path) == length:
            results.append(path.copy())
            return
        for choice in (0, 1):
            path.append(choice)
            backtrack()
            path.pop()

    backtrack()
    return results

def has_binary_target(length, target_sum):
    def backtrack(depth, current_sum):
        if current_sum > target_sum:
            return False
        if depth == length:
            return current_sum == target_sum
        return (
            backtrack(depth + 1, current_sum)
            or backtrack(depth + 1, current_sum + 1)
        )
    return backtrack(0, 0)

def unique_subsets(numbers):
    numbers = sorted(numbers)
    results, path = [], []
    def backtrack(start):
        results.append(path.copy())
        for index in range(start, len(numbers)):
            if index > start and numbers[index] == numbers[index - 1]:
                continue
            path.append(numbers[index])
            backtrack(index + 1)
            path.pop()
    backtrack(0)
    return results

def combinations(numbers, k):
    results, path = [], []
    def backtrack(start):
        if len(path) == k:
            results.append(path.copy())
            return
        for index in range(start, len(numbers)):
            path.append(numbers[index])
            backtrack(index + 1)
            path.pop()
    backtrack(0)
    return results

print(combinations([1, 2, 3], 2))  # [[1, 2], [1, 3], [2, 3]]

def combinations_pruned(numbers, k):
    results, path = [], []
    def backtrack(start):
        if len(path) == k:
            results.append(path.copy()); return
        needed = k - len(path)
        last_start = len(numbers) - needed
        for index in range(start, last_start + 1):
            path.append(numbers[index])
            backtrack(index + 1)
            path.pop()
    backtrack(0)
    return results
